INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2950, 'supplement', '/ˈsʌplɪmənt/', 'noun, verb', '{"zh-TW":["補充；補充物","補充"],"en":["something added to complete","to add to something"]}', NULL, 'supplement income / dietary supplement / supplement with', '[{"en":"Many freelancers supplement their income with part-time work.","zh-TW":"許多自由工作者用兼職來補充收入。"},{"en":"The report is supplemented with charts.","zh-TW":"報告附有圖表作為補充。"}]', '{"noun":"supplement","verb":"supplement","adjective":"supplementary"}', NULL, 4, 2950, 724),
(2951, 'supplier', '/səˈplaɪər/', 'noun', '{"zh-TW":["供應商"],"en":["a company that provides goods or services to another business"]}', NULL, 'key supplier / supplier relationship / preferred supplier / supplier evaluation', '[{"en":"The company maintains long-term relationships with key suppliers.","zh-TW":"公司與關鍵供應商保持長期關係。"},{"en":"A supplier audit was conducted to verify quality standards.","zh-TW":"進行了供應商審計以驗證品質標準。"}]', '{"plural":"suppliers","verb":"supply"}', NULL, 3, 2951, NULL),
(2952, 'supply', '/səˈplaɪ/', 'noun, verb', '{"zh-TW":["供應；供給","供應；提供"],"en":["an amount available for use","to provide what is needed"]}', NULL, 'supply and demand / supply chain / supply shortage', '[{"en":"The supply chain was disrupted by the pandemic.","zh-TW":"供應鏈受到疫情的影響而中斷。"},{"en":"The company supplies parts to major automakers.","zh-TW":"這家公司為主要汽車製造商供應零件。"}]', '{"noun":"supply, supplier","verb":"supply"}', NULL, 2, 2952, 63),
(2953, 'support', '/səˈpɔːrt/', 'noun, verb', '{"zh-TW":["支持；支援","支持；贊助"],"en":["help or encouragement","to give assistance to"]}', NULL, 'customer support / technical support / support a proposal', '[{"en":"The proposal received strong support from management.","zh-TW":"該提案獲得了管理層的大力支持。"},{"en":"We provide 24/7 customer support.","zh-TW":"我們提供全天候客戶支援。"}]', '{"noun":"support, supporter","verb":"support","adjective":"supportive"}', NULL, 3, 2953, 225),
(2954, 'suppose', '/səˈpoʊz/', 'verb', '{"zh-TW":["假設；認為"],"en":["to assume; to believe"]}', NULL, 'be supposed to / I suppose / suppose that', '[{"en":"You are supposed to submit the form by today.","zh-TW":"你應該在今天之前提交表格。"},{"en":"I suppose we could try a different approach.","zh-TW":"我想我們可以嘗試不同的方法。"}]', '{"noun":"supposition","verb":"suppose","adjective":"supposed"}', NULL, 3, 2954, NULL),
(2955, 'suppress', '/səˈpres/', 'verb', '{"zh-TW":["壓制；抑制"],"en":["to prevent from being expressed or known"]}', NULL, 'suppress information / suppress competition / suppress dissent', '[{"en":"The company tried to suppress negative reviews.","zh-TW":"公司試圖壓制負面評論。"},{"en":"Rising interest rates suppressed consumer spending.","zh-TW":"利率上升抑制了消費支出。"}]', '{"noun":"suppression","verb":"suppress"}', NULL, 3, 2955, NULL),
(2956, 'sure', '/ʃʊr/', 'adjective', '{"zh-TW":["確定的；當然"],"en":["certain; confident"]}', NULL, 'make sure / for sure', '[{"en":"Make sure you save the file.","zh-TW":"確保你儲存了檔案。"},{"en":"We will finish on time for sure.","zh-TW":"我們肯定會準時完成。"}]', '{"adjective":"sure","adverb":"surely"}', NULL, 1, 2956, NULL),
(2957, 'surge', '/sɜːrdʒ/', 'noun, verb', '{"zh-TW":["激增；猛漲","急增；湧現"],"en":["a sudden large increase","to increase suddenly"]}', NULL, 'surge in demand / price surge / power surge', '[{"en":"There was a surge in online orders during the holiday.","zh-TW":"假期期間線上訂單激增。"},{"en":"Oil prices surged after the announcement.","zh-TW":"公告後油價猛漲。"}]', '{"noun":"surge","verb":"surge"}', NULL, 2, 2957, NULL),
(2958, 'surgery', '/ˈsɜːrdʒəri/', 'noun', '{"zh-TW":["手術；外科手術"],"en":["a medical operation to treat a physical condition"]}', NULL, 'undergo surgery / elective surgery', '[{"en":"The patient underwent surgery to remove the tumor.","zh-TW":"病患接受了手術以切除腫瘤。"},{"en":"Recovery from surgery may take several weeks.","zh-TW":"手術後的康復可能需要幾週時間。"}]', '{"verb":"operate","adjective":"surgical"}', NULL, 3, 2958, NULL),
(2959, 'surpass', '/sərˈpæs/', 'verb', '{"zh-TW":["超越；勝過"],"en":["to exceed or be better than"]}', NULL, 'surpass expectations / surpass a record / surpass competitors', '[{"en":"Sales surpassed expectations by 20%.","zh-TW":"銷售額超出預期20%。"},{"en":"The company surpassed its competitors in revenue.","zh-TW":"該公司在營收上超越了競爭對手。"}]', '{"verb":"surpass"}', NULL, 3, 2959, NULL),
(2960, 'surplus', '/ˈsɜːrpləs/', 'noun, adjective', '{"zh-TW":["剩餘；盈餘","多餘的"],"en":["an amount left over","more than what is needed"]}', NULL, 'budget surplus / trade surplus / surplus inventory', '[{"en":"The government reported a budget surplus.","zh-TW":"政府報告了預算盈餘。"},{"en":"Surplus inventory was sold at a discount.","zh-TW":"多餘的庫存以折扣價出售。"}]', '{"noun":"surplus","adjective":"surplus"}', NULL, 3, 2960, 939),
(2961, 'surprise', '/sərˈpraɪz/', 'noun', '{"zh-TW":["驚喜；意外"],"en":["an unexpected event"]}', NULL, 'come as a surprise / surprise visit', '[{"en":"The announcement came as no surprise.","zh-TW":"這個公告並不令人意外。"},{"en":"The CEO made a surprise visit.","zh-TW":"執行長進行了突擊訪視。"}]', '{"noun":"surprise","verb":"surprise","adjective":"surprising","adverb":"surprisingly"}', NULL, 3, 2961, NULL),
(2962, 'surveillance', '/sɜːrˈveɪləns/', 'noun', '{"zh-TW":["監控；監視"],"en":["close observation of a person or place"]}', NULL, 'under surveillance / surveillance camera / surveillance system', '[{"en":"The building is equipped with surveillance cameras.","zh-TW":"這棟建築配有監視攝影機。"},{"en":"The suspect was placed under surveillance.","zh-TW":"嫌疑人被置於監控之下。"}]', '{"noun":"surveillance","verb":"surveil"}', NULL, 4, 2962, NULL),
(2963, 'survey', '/ˈsɜːrveɪ/', 'noun, verb', '{"zh-TW":["調查；問卷","進行調查"],"en":["a study of opinions or conditions","to investigate"]}', NULL, 'conduct a survey / customer survey / survey results', '[{"en":"We conducted a customer satisfaction survey.","zh-TW":"我們進行了客戶滿意度調查。"},{"en":"The survey revealed key market trends.","zh-TW":"調查揭示了主要的市場趨勢。"}]', '{"noun":"survey, surveyor","verb":"survey"}', NULL, 2, 2963, 226),
(2964, 'survive', '/sərˈvaɪv/', 'verb', '{"zh-TW":["存活；度過","倖存"],"en":["to continue to live or exist"]}', NULL, 'survive a crisis / survival rate / survive competition', '[{"en":"Few small businesses survive beyond five years.","zh-TW":"很少有小企業能存活超過五年。"},{"en":"The company survived the economic downturn.","zh-TW":"這家公司撐過了經濟衰退。"}]', '{"noun":"survival, survivor","verb":"survive"}', NULL, 3, 2964, NULL),
(2965, 'susceptible', '/səˈseptəbl/', 'adjective', '{"zh-TW":["易受影響的；敏感的"],"en":["likely to be affected by something"]}', NULL, 'susceptible to / highly susceptible / susceptible to change', '[{"en":"The market is susceptible to sudden changes.","zh-TW":"市場容易受到突然變化的影響。"},{"en":"Older systems are more susceptible to cyber attacks.","zh-TW":"較舊的系統更容易受到網路攻擊。"}]', '{"noun":"susceptibility","adjective":"susceptible"}', NULL, 4, 2965, NULL),
(2966, 'suspect', '/səˈspekt/', 'verb, noun', '{"zh-TW":["懷疑；猜想","嫌疑犯"],"en":["to believe something is likely","a person thought to be guilty"]}', NULL, 'suspect fraud / suspect that / prime suspect', '[{"en":"Auditors suspect financial irregularities.","zh-TW":"審計員懷疑有財務違規行為。"},{"en":"I suspect the delay is due to supply issues.","zh-TW":"我懷疑延遲是由於供應問題。"}]', '{"noun":"suspect, suspicion","verb":"suspect","adjective":"suspicious, suspected"}', NULL, 3, 2966, NULL),
(2967, 'suspend', '/səˈspend/', 'verb', '{"zh-TW":["暫停；中止","懸掛"],"en":["to temporarily stop","to hang from above"]}', NULL, 'suspend operations / suspend trading / suspend an employee', '[{"en":"The company suspended trading of its shares.","zh-TW":"公司暫停了股票交易。"},{"en":"Operations were suspended due to safety concerns.","zh-TW":"因安全顧慮，營運已暫停。"}]', '{"noun":"suspension","verb":"suspend"}', NULL, 3, 2967, NULL),
(2968, 'suspension', '/səˈspɛnʃən/', 'noun', '{"zh-TW":["暫停；停職；中止"],"en":["the temporary stopping of something"]}', NULL, 'suspension of services / suspension without pay', '[{"en":"The employee received a suspension pending the investigation.","zh-TW":"員工在等待調查期間被暫停職務。"},{"en":"Service suspension was announced due to maintenance.","zh-TW":"由於維護工作，服務暫停已被宣布。"}]', '{"verb":"suspend","adjective":"suspended"}', NULL, 4, 2968, NULL),
(2969, 'sustain', '/səˈsteɪn/', 'verb', '{"zh-TW":["維持；承受","維持；持續","承受"],"en":["to maintain at a certain level","to suffer or experience","to maintain over time","to suffer or endure"]}', '{"prefix":{"text":"sus-","meaning":"under (從下)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"從下方支撐持住，即「維持」。"}', 'sustain growth / sustain an injury / sustainable development; sustain growth / sustain losses / sustainable development', '[{"en":"The economy cannot sustain this level of spending.","zh-TW":"經濟無法維持這種支出水平。"},{"en":"He sustained minor injuries in the accident.","zh-TW":"他在事故中受了輕傷。"},{"en":"The business needs to sustain profitability.","zh-TW":"企業需要維持盈利能力。"},{"en":"The company sustained heavy losses last year.","zh-TW":"公司去年蒙受了重大損失。"}]', '{"adjective":"sustainable","noun":"sustainability","verb":"sustain"}', NULL, 3, 2969, 227),
(2970, 'sustainability', '/səˌsteɪnəˈbɪlɪti/', 'noun', '{"zh-TW":["可持續性；永續性"],"en":["meeting current needs without compromising future needs"]}', NULL, 'corporate sustainability / sustainability report / sustainability goals', '[{"en":"The company published its first sustainability report.","zh-TW":"公司發布了第一份永續報告。"},{"en":"Sustainability is now a core pillar of our strategy.","zh-TW":"永續性現在是我們策略的核心支柱。"}]', '{"adjective":"sustainable","adverb":"sustainably"}', NULL, 5, 2970, 625),
(2971, 'sustainable', '/səˈsteɪnəbl/', 'adjective', '{"zh-TW":["可持續的；永續的"],"en":["able to be maintained over the long term without depleting resources"]}', NULL, 'sustainable growth / sustainable business / sustainable practices', '[{"en":"The company shifted to sustainable packaging to reduce waste.","zh-TW":"公司轉向可持續包裝以減少廢物。"},{"en":"Sustainable growth requires balancing short-term gains with long-term health.","zh-TW":"可持續增長需要平衡短期收益和長期健康。"}]', '{"adverb":"sustainably","noun":"sustainability"}', NULL, 4, 2971, 466),
(2972, 'swap', '/swɒp/', 'noun', '{"zh-TW":["互換合約；掉期"],"en":["a derivative contract exchanging cash flows between two parties"]}', NULL, 'interest rate swap / currency swap / credit default swap', '[{"en":"The company entered an interest rate swap to fix borrowing costs.","zh-TW":"公司簽訂了利率互換合約以固定借貸成本。"},{"en":"Currency swaps help companies manage foreign exchange risk.","zh-TW":"貨幣互換幫助公司管理外匯風險。"}]', '{"verb":"swap"}', NULL, 1, 2972, NULL),
(2973, 'sweet', '/swiːt/', 'adjective', '{"zh-TW":["甜的；親切的"],"en":["having the taste of sugar","kind and pleasant"]}', NULL, 'sweet spot / sweet deal', '[{"en":"We found the sweet spot for pricing.","zh-TW":"我們找到了定價的最佳點。"},{"en":"That is a sweet deal for both parties.","zh-TW":"對雙方來說都是很棒的交易。"}]', '{"adjective":"sweet","noun":"sweetness","adverb":"sweetly","verb":"sweeten"}', NULL, 2, 2973, NULL),
(2974, 'switch', '/swɪtʃ/', 'noun, verb', '{"zh-TW":["轉換；開關","切換；轉變"],"en":["a change; a device for making connections","to change from one thing to another"]}', NULL, 'switch to / make the switch / switch providers', '[{"en":"Many companies switched to remote work.","zh-TW":"許多公司轉換為遠端工作。"},{"en":"Customers can switch providers without penalty.","zh-TW":"客戶可以無需罰款更換供應商。"}]', '{"noun":"switch","verb":"switch"}', NULL, 2, 2974, NULL),
(2975, 'syllabus', '/ˈsɪləbəs/', 'noun', '{"zh-TW":["課程大綱","教學大綱"],"en":["an outline of subjects in a course","a document showing what will be taught in a course"]}', NULL, 'course syllabus / follow the syllabus; course syllabus / on the syllabus', '[{"en":"The training syllabus is updated annually.","zh-TW":"培訓大綱每年更新。"},{"en":"Please review the syllabus before the course begins.","zh-TW":"請在課程開始前閱讀課程大綱。"},{"en":"Check the syllabus for due dates.","zh-TW":"查看教學大綱上的截止日期。"},{"en":"The syllabus outlines all assignments.","zh-TW":"教學大綱列出了所有作業。"}]', '{"noun":"syllabus"}', NULL, 3, 2975, NULL),
(2976, 'symbol', '/ˈsɪmbl/', 'noun', '{"zh-TW":["符號；象徵"],"en":["something that represents something else"]}', NULL, 'symbol of / stock symbol / status symbol', '[{"en":"The logo is a symbol of quality and trust.","zh-TW":"這個標誌是品質和信任的象徵。"},{"en":"Check the stock symbol before placing an order.","zh-TW":"下單前請確認股票代碼。"}]', '{"noun":"symbol, symbolism","verb":"symbolize","adjective":"symbolic"}', NULL, 2, 2976, NULL),
(2977, 'sympathetic', '/ˌsɪmpəˈθetɪk/', 'adjective', '{"zh-TW":["同情的；有同感的"],"en":["feeling or showing concern for someone''s misfortune"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"path","meaning":"feeling (感受)"},"suffix":{"text":"-etic","meaning":"relating to (相關的)"},"logic":"一起感受的，即「同情的」。"}', 'sympathetic to / sympathetic ear', '[{"en":"She was sympathetic to his problems.","zh-TW":"她對他的問題表示同情。"},{"en":"He found a sympathetic listener in his friend.","zh-TW":"他在朋友那裡找到了知心的傾聽者。"}]', '{"noun":"sympathy","verb":"sympathize"}', NULL, 4, 2977, NULL),
(2978, 'sympathy', '/ˈsɪmpəθi/', 'noun', '{"zh-TW":["同情；同感"],"en":["feelings of pity and sorrow for someone"]}', NULL, 'express sympathy / in sympathy with / earn sympathy', '[{"en":"We express our deepest sympathy for your loss.","zh-TW":"我們對您的損失表示最深切的同情。"},{"en":"Workers went on strike in sympathy with the fired employees.","zh-TW":"工人們為聲援被解雇的員工而罷工。"}]', '{"noun":"sympathy","adjective":"sympathetic","verb":"sympathize"}', NULL, 3, 2978, NULL),
(2979, 'symphony', '/ˈsɪmfəni/', 'noun', '{"zh-TW":["交響曲"],"en":["a long piece of music for a full orchestra"]}', '{"prefix":{"text":"sym-","meaning":"together (一起)"},"root":{"text":"phon","meaning":"sound (聲音)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"聲音在一起和諧，即「交響曲」。"}', 'symphony orchestra / compose a symphony', '[{"en":"Beethoven''s Ninth Symphony is world-famous.","zh-TW":"貝多芬第九號交響曲舉世聞名。"},{"en":"We attended a symphony concert last night.","zh-TW":"我們昨晚參加了一場交響音樂會。"}]', '{"adjective":"symphonic"}', NULL, 3, 2979, NULL),
(2980, 'symptom', '/ˈsɪmptəm/', 'noun', '{"zh-TW":["症狀"],"en":["a sign of a disease or illness"]}', NULL, 'common symptom / report symptoms', '[{"en":"Tell your doctor about all your symptoms.","zh-TW":"將您的所有症狀告知醫生。"},{"en":"The most common symptoms include fever and fatigue.","zh-TW":"最常見的症狀包括發燒和疲勞。"}]', '{"adjective":"symptomatic"}', NULL, 3, 2980, NULL),
(2981, 'syndicate', '/ˈsɪndɪkɪt/', 'noun', '{"zh-TW":["辛迪加；聯合組織"],"en":["a group of individuals or organizations combined for a purpose"]}', NULL, 'banking syndicate / loan syndicate', '[{"en":"A banking syndicate financed the project.","zh-TW":"一個銀行聯合組織為專案提供了融資。"},{"en":"The loan was arranged through a syndicate.","zh-TW":"貸款透過聯貸組織安排。"}]', '{"noun":"syndicate","verb":"syndicate","noun2":"syndication"}', NULL, 3, 2981, NULL),
(2982, 'synergize', '/ˈsɪnərdʒaɪz/', 'verb', '{"zh-TW":["協同運作；發揮協同效應"],"en":["to work together in a way that produces a combined effect greater than the parts"]}', NULL, 'synergize efforts / synergize teams', '[{"en":"The two departments synergized to deliver a stronger proposal.","zh-TW":"兩個部門協同運作，提交了更有力的提案。"},{"en":"Great teams synergize their diverse skills for better results.","zh-TW":"優秀的團隊協同發揮各自的多元技能以獲得更好的成果。"}]', '{"noun":"synergy","adjective":"synergistic"}', NULL, 3, 2982, NULL),
(2983, 'synergy', '/ˈsɪnədʒi/', 'noun', '{"zh-TW":["協同效應"],"en":["the combined benefit exceeding the sum of individual parts, often in mergers"]}', NULL, 'realize synergies / cost synergies / revenue synergies / merger synergies', '[{"en":"The merger was expected to generate $50 million in cost synergies.","zh-TW":"合併預計將產生5000萬美元的成本協同效應。"},{"en":"Synergies from the acquisition took two years to fully materialize.","zh-TW":"收購的協同效應花了兩年時間才完全實現。"}]', '{"adjective":"synergistic","verb":"synergize"}', NULL, 3, 2983, NULL),
(2984, 'synthetic', '/sɪnˈθetɪk/', 'adjective', '{"zh-TW":["合成的；人造的"],"en":["made by chemical synthesis; not natural"]}', NULL, 'synthetic materials / synthetic fibers / synthetic data', '[{"en":"The jacket is made of synthetic fibers.","zh-TW":"這件夾克是用合成纖維製成的。"},{"en":"Synthetic data is used to train AI models.","zh-TW":"合成數據被用來訓練AI模型。"}]', '{"noun":"synthesis","adjective":"synthetic","verb":"synthesize"}', NULL, 3, 2984, NULL),
(2985, 'system', '/ˈsɪstəm/', 'noun', '{"zh-TW":["系統；體系"],"en":["a set of connected things forming a complex whole"]}', NULL, 'operating system / system failure / management system', '[{"en":"The new IT system improves efficiency.","zh-TW":"新的資訊系統提高了效率。"},{"en":"We implemented a quality management system.","zh-TW":"我們實施了品質管理系統。"}]', '{"noun":"system","adjective":"systematic, systemic","adverb":"systematically"}', NULL, 2, 2985, 467),
(2986, 'systematic', 'ˌsɪstɪˈmætɪk', 'adjective', '{"zh-TW":["系統性的；有條理的","有計劃的"],"en":["following a planned system","methodical"]}', NULL, 'systematic approach/systematic review', '[{"en":"Use a systematic approach to problem-solving.","zh-TW":"使用系統性的方法解決問題。"}]', '{"adverb":"systematically"}', NULL, 4, 2986, NULL),
(2987, 'table', '/ˈteɪbəl/', 'noun', '{"zh-TW":["【主要意義-名詞】桌子；表格","【次要意義-動詞（英式）】提出討論；將議題列入議程","【次要意義-動詞（美式）】擱置；延後討論"],"en":["[primary - noun] a piece of furniture with a flat top","[secondary - verb (British English)] to present something for discussion","[secondary - verb (American English)] to postpone discussion of something"]}', NULL, 'table a motion / table a proposal / table a discussion', '[{"en":"The committee tabled the budget proposal until next month. (AmE)","zh-TW":"委員會將預算提案延後到下個月討論。（美式）"},{"en":"The union tabled new wage demands at the meeting. (BrE)","zh-TW":"工會在會議上提出了新的薪資要求。（英式）"},{"en":"The issue was tabled for further review by the board.","zh-TW":"該議題被董事會擱置以供進一步審查。"}]', '{"noun":"tabling"}', '動詞 table 在美式和英式英語中意思相反！美式表示「擱置」，英式表示「提出」，TOEIC 考試以美式英語為主，此動詞常讓考生困惑。', 2, 2987, NULL),
(2988, 'tablet', '/ˈtæblɪt/', 'noun', '{"zh-TW":["平板電腦"],"en":["a flat portable computer with a touchscreen"]}', NULL, 'tablet computer / tablet screen', '[{"en":"She reads books on her tablet.","zh-TW":"她用平板電腦看書。"},{"en":"Tablets are popular for online learning.","zh-TW":"平板電腦在線上學習中很受歡迎。"}]', NULL, NULL, 2, 2988, NULL),
(2989, 'tackle', '/ˈtækl/', 'verb, noun', '{"zh-TW":["處理；解決","應對"],"en":["to deal with a difficult problem","equipment or an act of confronting"]}', NULL, 'tackle a problem / tackle the issue / tackle challenges', '[{"en":"We must tackle the issue of rising costs.","zh-TW":"我們必須處理成本上漲的問題。"},{"en":"The team tackled the project head-on.","zh-TW":"團隊直接面對這個專案。"}]', '{"noun":"tackle","verb":"tackle"}', NULL, 2, 2989, NULL),
(2990, 'tactics', '/ˈtæktɪks/', 'noun', '{"zh-TW":["策略；戰術"],"en":["planned actions to achieve a specific end"]}', NULL, 'marketing tactics / negotiation tactics / change tactics', '[{"en":"The sales team adopted new marketing tactics.","zh-TW":"銷售團隊採用了新的行銷策略。"},{"en":"Aggressive tactics may backfire.","zh-TW":"激進的策略可能會適得其反。"}]', '{"noun":"tactics, tactician","adjective":"tactical","adverb":"tactically"}', NULL, 3, 2990, NULL),
(2991, 'tagline', '/ˈtæɡlaɪn/', 'noun', '{"zh-TW":["廣告語；標語"],"en":["a short memorable phrase associated with a brand or product"]}', NULL, 'create a tagline / memorable tagline / brand tagline', '[{"en":"Their tagline ''Just Do It'' is one of the most recognized in the world.","zh-TW":"他們的廣告語「Just Do It」是世界上最知名的之一。"},{"en":"The new tagline better reflected the brand''s commitment to innovation.","zh-TW":"新標語更好地反映了品牌對創新的承諾。"}]', '{"alternative":"slogan"}', NULL, 3, 2991, NULL),
