(2997, 'talk', '/tɔːk/', 'verb', '{"zh-TW":["說話；談論"],"en":["to speak","to discuss"]}', NULL, 'talk about / small talk', '[{"en":"Let''s talk about the budget.","zh-TW":"我們來談談預算。"},{"en":"He gave a talk on leadership.","zh-TW":"他做了一場關於領導力的演講。"}]', '{"verb":"talk","noun":"talk","noun2":"talker"}', NULL, 1, 2997, NULL),
