(2999, 'target', '/ˈtɑːrɡɪt/', 'noun, verb', '{"zh-TW":["目標；對象","以...為目標"],"en":["an aim or objective","to direct at a particular group"]}', NULL, 'target market / target audience / meet the target', '[{"en":"We exceeded our sales target by 10%.","zh-TW":"我們超額完成了10%的銷售目標。"},{"en":"The campaign targets young professionals.","zh-TW":"該活動以年輕專業人士為目標對象。"}]', '{"noun":"target","verb":"target","adjective":"targeted"}', NULL, 2, 2999, 228);
