(3010, 'telecommute', '/ˈtɛlɪkəˌmjuːt/', 'verb', '{"zh-TW":["遠距工作；居家上班"],"en":["to work from home using telecommunications technology"]}', NULL, 'telecommute full-time / option to telecommute', '[{"en":"She telecommutes three days a week.","zh-TW":"她每週遠距工作三天。"},{"en":"Telecommuting reduces office space requirements and commuting time.","zh-TW":"遠距工作減少了辦公空間需求和通勤時間。"}]', '{"noun":"telecommuting"}', NULL, 4, 3010, NULL),
(3011, 'teleconference', '/ˈtɛlɪˌkɒnfərəns/', 'noun', '{"zh-TW":["電話會議；視訊會議"],"en":["a conference held by telephone or video"]}', NULL, 'host a teleconference / join a teleconference', '[{"en":"The team held a teleconference to discuss the merger.","zh-TW":"團隊舉行了電話會議討論合併事宜。"},{"en":"Teleconferences allow teams in different time zones to meet.","zh-TW":"電話會議使不同時區的團隊能夠開會。"}]', '{"verb":"teleconference"}', NULL, 5, 3011, NULL),
(3012, 'telemedicine', '/ˈtɛlɪmɛdɪsɪn/', 'noun', '{"zh-TW":["遠距醫療；遠程醫療"],"en":["the delivery of healthcare via technology from a distance"]}', NULL, 'use telemedicine / telemedicine consultation', '[{"en":"Telemedicine allows patients to consult doctors remotely.","zh-TW":"遠距醫療允許患者遠程諮詢醫生。"},{"en":"The telemedicine service is available 24 hours a day.","zh-TW":"遠距醫療服務全天24小時提供。"}]', '{"adjective":"telemedical"}', NULL, 4, 3012, NULL),
