(3016, 'temperature', '/ˈtemprətʃər/', 'noun', '{"zh-TW":["溫度"],"en":["the degree of heat or cold in a place"]}', '{"root":{"text":"temper","meaning":"mix/moderate (調節)"},"suffix":{"text":"-ature","meaning":"result (結果)"},"logic":"調節的結果狀態，即「溫度」。"}', 'room temperature / body temperature / high temperature', '[{"en":"The temperature dropped below zero last night.","zh-TW":"昨晚溫度降到零度以下。"},{"en":"What is the temperature outside?","zh-TW":"外面的溫度是多少？"}]', NULL, NULL, 4, 3016, NULL),
