(3019, 'tenancy', '/ˈtenənsi/', 'noun', '{"zh-TW":["租賃；租用期"],"en":["the period during which a property is occupied by a tenant"]}', NULL, 'joint tenancy / tenancy agreement / end tenancy / tenancy deposit', '[{"en":"The tenancy agreement specifies a one-year term.","zh-TW":"租賃協議規定了一年的期限。"},{"en":"She gave notice to terminate her tenancy at the end of the month.","zh-TW":"她通知在月底終止租賃關係。"}]', '{"noun":"tenant","verb":"tenant"}', NULL, 3, 3019, NULL),
(3020, 'tenant', '/ˈtenənt/', 'noun', '{"zh-TW":["租戶；承租人"],"en":["a person who occupies rented property"]}', NULL, 'tenant agreement / commercial tenant / existing tenant', '[{"en":"The building has several commercial tenants.","zh-TW":"這棟大樓有數個商業租戶。"},{"en":"Tenants must give 30 days'' notice before moving out.","zh-TW":"租戶搬出前須提前30天通知。"}]', '{"noun":"tenant, tenancy"}', NULL, 2, 3020, NULL),
(3021, 'tend', '/tend/', 'verb', '{"zh-TW":["傾向於；趨向"],"en":["to be likely to behave in a particular way"]}', NULL, 'tend to / tend toward / tendency', '[{"en":"Prices tend to rise during peak season.","zh-TW":"旺季期間價格往往會上漲。"},{"en":"Consumers tend to prefer eco-friendly products.","zh-TW":"消費者傾向於偏好環保產品。"}]', '{"noun":"tendency","verb":"tend"}', NULL, 1, 3021, NULL),
(3022, 'tender', '/ˈtendər/', 'noun, verb, adjective', '{"zh-TW":["投標；標書","投標","溫柔的；嫩的"],"en":["a formal offer to supply goods","to make a formal offer","gentle; soft"]}', NULL, 'submit a tender / tender process / invitation to tender', '[{"en":"Five companies submitted tenders for the project.","zh-TW":"五家公司為該專案提交了投標書。"},{"en":"The tender deadline is next Friday.","zh-TW":"投標截止日期是下週五。"}]', '{"noun":"tender","verb":"tender"}', NULL, 2, 3022, NULL),
(3023, 'tenders', '/ˈtendərz/', 'noun', '{"zh-TW":["投標書；招標"],"en":["formal offers to provide goods or services at a stated price"]}', NULL, 'submit tenders / invite tenders / evaluate tenders', '[{"en":"Three companies submitted tenders for the construction contract.","zh-TW":"三家公司提交了建築合約的投標書。"},{"en":"The lowest tender was accepted after quality assessment.","zh-TW":"在品質評估後接受了最低的投標書。"}]', '{"singular":"tender","verb":"tender"}', NULL, 3, 3023, NULL),
