(3025, 'tenure', '/ˈtenjər/', 'noun', '{"zh-TW":["任期；任職期間"],"en":["the holding of an office or position"]}', NULL, 'during one''s tenure / job tenure / tenure track', '[{"en":"During her tenure, revenue doubled.","zh-TW":"在她任職期間，營收翻倍。"},{"en":"Average employee tenure at the company is five years.","zh-TW":"員工在公司的平均任期是五年。"}]', '{"noun":"tenure","adjective":"tenured"}', NULL, 2, 3025, NULL),
(3026, 'term', 'tɜːrm', 'noun', '{"zh-TW":["【主要意義-名詞】術語；學期","【次要意義-動詞】稱呼；稱為","【次要意義-名詞】任期；任職期間","【次要意義-複數名詞】條款；條件；協議內容"],"en":["[primary - noun] a word or expression; a fixed period of time","[secondary - verb] to give a name or label to something","[secondary - noun] a period of office or service","[secondary - plural noun] the conditions of an agreement"]}', NULL, 'in terms of / terms and conditions / come to terms / term of office', '[{"en":"The agreement terms must be reviewed before signing the contract.","zh-TW":"在簽署合約之前必須審查協議條款。"},{"en":"In terms of profitability, this has been our best year.","zh-TW":"就盈利能力而言，這是我們最好的一年。"},{"en":"She served a full term as director before retiring.","zh-TW":"她在退休前完整擔任了一個任期的董事。"}]', '{"adjective":"terminal, long-term, short-term"}', 'terms（複數）= 「條款/條件」是 TOEIC 合約類文章的必考詞，in terms of（就……而言）是高頻搭配，動詞 term = 「稱呼/稱為」也常見於正式文章。', 1, 3026, NULL),
(3027, 'terminal', '/ˈtɜːrmɪnəl/', 'noun', '{"zh-TW":["航站樓；終點站"],"en":["a building at an airport where passengers arrive and depart"]}', NULL, 'international terminal / airport terminal', '[{"en":"Flight 302 departs from Terminal B.","zh-TW":"302號航班從B航站樓出發。"},{"en":"The new terminal has more shopping options.","zh-TW":"新航站樓有更多購物選擇。"}]', '{"adjective":"terminal"}', NULL, 3, 3027, NULL),
(3028, 'terminate', '/ˈtɜːrmɪneɪt/', 'verb', '{"zh-TW":["終止；結束"],"en":["to bring to an end"]}', NULL, 'terminate a contract / terminate employment / terminate an agreement', '[{"en":"Either party may terminate the contract with 30 days'' notice.","zh-TW":"任何一方均可提前30天通知終止合約。"},{"en":"His employment was terminated due to misconduct.","zh-TW":"他因不當行為而被解雇。"}]', '{"noun":"termination","verb":"terminate"}', NULL, 3, 3028, 65),
(3029, 'termination', '/ˌtɜːrmɪˈneɪʃən/', 'noun', '{"zh-TW":["解僱；終止"],"en":["the ending of an employee''s contract by the employer"]}', NULL, 'termination letter / wrongful termination / contract termination', '[{"en":"The termination was effective immediately.","zh-TW":"解僱即刻生效。"},{"en":"She filed a lawsuit claiming wrongful termination.","zh-TW":"她提起訴訟，聲稱被不當解僱。"}]', '{"verb":"terminate","adjective":"terminated"}', NULL, 4, 3029, 626),
(3030, 'territory', '/ˈterɪtɔːri/', 'noun', '{"zh-TW":["領土；區域","銷售區域"],"en":["an area of land; a region assigned to someone"]}', NULL, 'sales territory / expand into new territory / uncharted territory', '[{"en":"The sales rep covers the entire eastern territory.","zh-TW":"這位銷售代表負責整個東部區域。"},{"en":"We are expanding into new territory in Southeast Asia.","zh-TW":"我們正在東南亞拓展新領域。"}]', '{"noun":"territory","adjective":"territorial"}', NULL, 3, 3030, NULL),
(3031, 'testify', '/ˈtestɪfaɪ/', 'verb', '{"zh-TW":["作證；證明"],"en":["to give evidence as a witness"]}', NULL, 'testify in court / testify against / testify to', '[{"en":"The accountant testified in the fraud case.","zh-TW":"會計師在詐欺案中作證。"},{"en":"The results testify to the success of the program.","zh-TW":"結果證明了該計畫的成功。"}]', '{"noun":"testimony, testimonial","verb":"testify"}', NULL, 3, 3031, NULL),
(3032, 'testimonial', '/ˌtɛstɪˈməʊniəl/', 'noun', '{"zh-TW":["客戶評價；推薦信"],"en":["a written or spoken statement endorsing a product or person"]}', NULL, 'customer testimonial / positive testimonial', '[{"en":"Customer testimonials can greatly influence buying decisions.","zh-TW":"客戶評價可以極大地影響購買決策。"},{"en":"The website features testimonials from satisfied clients.","zh-TW":"網站上展示了滿意顧客的評價。"}]', NULL, NULL, 4, 3032, NULL),
