(3034, 'textbook', '/ˈtɛkstbʊk/', 'noun', '{"zh-TW":["教科書"],"en":["a book used for studying a subject"]}', NULL, 'textbook example / buy textbooks', '[{"en":"Textbooks are expensive.","zh-TW":"教科書很貴。"},{"en":"This is a textbook example of good design.","zh-TW":"這是好設計的典型範例。"}]', NULL, NULL, 3, 3034, NULL),
(3035, 'theater', '/ˈθiːətər/', 'noun', '{"zh-TW":["劇院；戲劇"],"en":["a building for performances","the art of writing and performing plays"]}', '{"root":{"text":"thea","meaning":"view (觀看)"},"suffix":{"text":"-ter","meaning":"place (場所)"},"logic":"觀看表演的場所，即「劇院」。"}', 'movie theater / theater performance', '[{"en":"We saw a play at the local theater.","zh-TW":"我們在當地劇院看了一場戲。"},{"en":"She studied theater in college.","zh-TW":"她在大學主修戲劇。"}]', '{"adjective":"theatrical"}', NULL, 3, 3035, NULL),
(3036, 'therapy', '/ˈθɛrəpi/', 'noun', '{"zh-TW":["治療；療法"],"en":["treatment for a physical or mental condition"]}', NULL, 'physical therapy / therapy session', '[{"en":"Physical therapy was recommended after the knee surgery.","zh-TW":"膝蓋手術後建議進行物理治療。"},{"en":"She attends therapy sessions every week to manage stress.","zh-TW":"她每週參加療法課程來管理壓力。"}]', '{"verb":"treat","noun":"therapist","adjective":"therapeutic"}', NULL, 3, 3036, NULL),
(3037, 'thesis', '/ˈθiːsɪs/', 'noun', '{"zh-TW":["論文；論點"],"en":["a long essay for a degree","a theory to be proved","a long piece of writing for a degree"]}', NULL, 'master''s thesis / central thesis; master''s thesis / thesis statement', '[{"en":"Her master''s thesis focused on supply chain efficiency.","zh-TW":"她的碩士論文專注於供應鏈效率。"},{"en":"The central thesis of the report is cost reduction.","zh-TW":"報告的核心論點是成本削減。"},{"en":"She''s writing her master''s thesis.","zh-TW":"她正在寫碩士論文。"},{"en":"Your thesis statement should be clear.","zh-TW":"你的論點應該要清楚。"}]', '{"noun":"thesis","plural":"theses"}', NULL, 2, 3037, NULL),
(3038, 'think', 'θɪŋk', 'verb', '{"zh-TW":["思考；認為","考慮"],"en":["to use your mind","to hold an opinion"]}', NULL, 'think about/of/outside the box', '[{"en":"Think carefully before making a decision.","zh-TW":"做決定前要仔細思考。"}]', '{"noun":"thought, thinker","adjective":"thoughtful","adverb":"thoughtfully"}', NULL, 2, 3038, NULL),
(3039, 'thorough', '/ˈθʌroʊ/', 'adjective', '{"zh-TW":["徹底的；詳盡的"],"en":["complete with attention to every detail"]}', NULL, 'thorough investigation / thorough review / thorough analysis', '[{"en":"We conducted a thorough investigation.","zh-TW":"我們進行了徹底的調查。"},{"en":"The report requires a more thorough analysis.","zh-TW":"這份報告需要更詳盡的分析。"}]', '{"adjective":"thorough","adverb":"thoroughly","noun":"thoroughness"}', NULL, 3, 3039, NULL),
(3040, 'thousand', 'ˈθaʊzənd', 'noun', '{"zh-TW":["千；一千","大量"],"en":["the number 1,000","a large round number"]}', NULL, 'a thousand/thousands of', '[{"en":"Thousands of customers visit our site daily.","zh-TW":"每天有數千名客戶訪問我們的網站。"}]', '{"adjective":"thousand","adverb":"thousandfold"}', NULL, 3, 3040, NULL),
(3041, 'threat', '/θret/', 'noun', '{"zh-TW":["威脅；恐嚇"],"en":["a statement of intention to harm; a danger"]}', NULL, 'pose a threat / security threat / under threat', '[{"en":"Cybersecurity threats are increasing globally.","zh-TW":"全球網路安全威脅正在增加。"},{"en":"Climate change poses a serious threat to businesses.","zh-TW":"氣候變遷對企業構成嚴重威脅。"}]', '{"noun":"threat","verb":"threaten","adjective":"threatening"}', NULL, 2, 3041, NULL),
(3042, 'threshold', '/ˈθreʃhoʊld/', 'noun', '{"zh-TW":["門檻；起始點"],"en":["the level at which something starts"]}', NULL, 'tax threshold / below the threshold / pain threshold', '[{"en":"Income below the threshold is tax-free.","zh-TW":"低於門檻的收入免稅。"},{"en":"The company has reached the profitability threshold.","zh-TW":"公司已達到盈利門檻。"}]', '{"noun":"threshold"}', NULL, 3, 3042, 941),
(3043, 'thrive', '/θraɪv/', 'verb', '{"zh-TW":["蓬勃發展；興旺"],"en":["to grow or develop well"]}', NULL, 'thrive in / thrive on / thriving business', '[{"en":"Small businesses thrived during the digital boom.","zh-TW":"小型企業在數位化潮流中蓬勃發展。"},{"en":"She thrives under pressure.","zh-TW":"她在壓力下表現出色。"}]', '{"verb":"thrive","adjective":"thriving"}', NULL, 2, 3043, NULL),
(3044, 'throughput', '/ˈθruːpʊt/', 'noun', '{"zh-TW":["吞吐量；產出率"],"en":["the rate at which goods or transactions are processed"]}', NULL, 'increase throughput / production throughput / maximize throughput', '[{"en":"Removing the bottleneck increased the assembly line''s throughput.","zh-TW":"消除瓶頸增加了裝配線的吞吐量。"},{"en":"The port''s throughput capacity was expanded to handle more vessels.","zh-TW":"港口的吞吐能力被擴大以處理更多船隻。"}]', NULL, NULL, 4, 3044, NULL),
(3045, 'thunder', '/ˈθʌndər/', 'noun', '{"zh-TW":["雷聲"],"en":["the loud sound following lightning"]}', '{"root":{"text":"thunder","meaning":"resound (回響)"},"logic":"源自古英語 þunor（巨響）。"}', 'thunder and lightning / thunderstorm', '[{"en":"We heard thunder in the distance.","zh-TW":"我們聽到遠處的雷聲。"},{"en":"The dog is afraid of thunder.","zh-TW":"這隻狗怕打雷。"}]', '{"noun":"thunderstorm","adjective":"thunderous"}', NULL, 3, 3045, NULL),
(3046, 'ticket', '/ˈtɪkɪt/', 'noun', '{"zh-TW":["工單；票單"],"en":["a record of a service request or issue submitted to a support team"]}', NULL, 'open a ticket / resolve a ticket / support ticket / ticket queue', '[{"en":"A support ticket was opened for the billing error.","zh-TW":"為帳單錯誤開立了一張支援工單。"},{"en":"The ticket was escalated to the second-level support team.","zh-TW":"工單被升級到第二級支援團隊。"}]', '{"verb":"ticket","plural":"tickets"}', NULL, 2, 3046, NULL),
(3047, 'tight', '/taɪt/', 'adjective', '{"zh-TW":["緊的；嚴格的","資金緊張的"],"en":["fixed or held firmly","limited or restricted"]}', NULL, 'tight deadline / tight budget / tight schedule', '[{"en":"We are working under a very tight deadline.","zh-TW":"我們在非常緊迫的截止日期下工作。"},{"en":"The budget is tight this quarter.","zh-TW":"本季度預算緊張。"}]', '{"adjective":"tight","adverb":"tightly","verb":"tighten"}', NULL, 2, 3047, NULL),
(3048, 'time', 'taɪm', 'noun', '{"zh-TW":["時間；次數","時期"],"en":["the progression of events","an instance or occasion"]}', NULL, 'lead time/full-time', '[{"en":"Delivery lead time is two weeks.","zh-TW":"交貨前置時間為兩週。"}]', '{"verb":"time","adjective":"timely","adverb":"timely"}', NULL, 1, 3048, NULL),
(3049, 'time-sensitive', 'taɪm ˈsɛnsɪtɪv', 'adjective', '{"zh-TW":["時效性強的；緊迫的","有時間限制的"],"en":["needing to be done quickly","urgent"]}', NULL, 'time-sensitive request/time-sensitive matter', '[{"en":"This is a time-sensitive matter.","zh-TW":"這是一個時效性很強的事項。"}]', NULL, NULL, 5, 3049, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(3050, 'time-to-market', '/taɪm tuː ˈmɑːrkɪt/', 'noun', '{"zh-TW":["上市時間"],"en":["the time elapsed between a product''s conception and its availability for sale"]}', NULL, 'reduce time-to-market / faster time-to-market', '[{"en":"Agile development methods significantly reduced the product''s time-to-market.","zh-TW":"敏捷開發方法顯著縮短了產品的上市時間。"},{"en":"Shorter time-to-market gives companies a first-mover advantage.","zh-TW":"較短的上市時間為公司提供了先發優勢。"}]', NULL, NULL, 5, 3050, NULL),
(3051, 'timeline', '/ˈtaɪmlaɪn/', 'noun', '{"zh-TW":["時間表；時間軸"],"en":["a schedule showing the order and timing of events"]}', NULL, 'project timeline / revise the timeline', '[{"en":"The project timeline was extended by two weeks.","zh-TW":"項目時間表延長了兩週。"},{"en":"All team members must adhere to the agreed timeline.","zh-TW":"所有團隊成員必須遵守商定的時間表。"}]', NULL, NULL, 3, 3051, 233),
(3052, 'timely', '/ˈtaɪmli/', 'adjective', '{"zh-TW":["及時的；適時的"],"en":["done at a suitable or opportune time"]}', NULL, 'timely manner / timely delivery / timely response', '[{"en":"Please respond in a timely manner.","zh-TW":"請及時回覆。"},{"en":"Timely delivery is crucial for customer satisfaction.","zh-TW":"及時交貨對客戶滿意度至關重要。"}]', '{"adjective":"timely","noun":"timeliness"}', NULL, 2, 3052, NULL),
(3053, 'tip', '/tɪp/', 'noun', '{"zh-TW":["小費"],"en":["a sum of money given to a service worker"]}', NULL, 'leave a tip / generous tip', '[{"en":"It is customary to leave a 15 to 20 percent tip.","zh-TW":"習慣上會留下15到20%的小費。"},{"en":"The waiter was pleased with the generous tip.","zh-TW":"服務生對豐厚的小費感到高興。"}]', '{"verb":"tip"}', NULL, 1, 3053, NULL),
(3054, 'title', '/ˈtaɪtəl/', 'noun', '{"zh-TW":["產權；所有權"],"en":["legal ownership of property"]}', NULL, 'clear title / title search / transfer title / title deed', '[{"en":"The title was transferred to the new owner after completion.","zh-TW":"產權在交割後轉移給新業主。"},{"en":"A title search confirmed there were no liens on the property.","zh-TW":"產權搜查確認物業上沒有留置權。"}]', '{"adjective":"titled"}', NULL, 2, 3054, NULL),
(3055, 'tolerance', '/ˈtɑːlərəns/', 'noun', '{"zh-TW":["容忍；寬容","公差"],"en":["willingness to accept differences","the allowable variation"]}', NULL, 'zero tolerance / risk tolerance / tolerance level', '[{"en":"The company has a zero-tolerance policy on harassment.","zh-TW":"公司對騷擾採取零容忍政策。"},{"en":"Investors have different levels of risk tolerance.","zh-TW":"投資者有不同程度的風險承受力。"}]', '{"noun":"tolerance","verb":"tolerate","adjective":"tolerant, tolerable"}', NULL, 3, 3055, NULL),
(3056, 'tolerant', '/ˈtɒlərənt/', 'adjective', '{"zh-TW":["容忍的；寬容的"],"en":["willing to accept views or behavior different from one''s own"]}', '{"root":{"text":"toler","meaning":"endure (忍受)"},"suffix":{"text":"-ant","meaning":"being (…的)"},"logic":"能忍受差異的，即「寬容的」。"}', 'tolerant of / tolerant society', '[{"en":"We should be tolerant of different opinions.","zh-TW":"我們應該容忍不同的意見。"},{"en":"She is very tolerant of her coworkers.","zh-TW":"她對同事很寬容。"}]', '{"noun":"tolerance","verb":"tolerate"}', NULL, 3, 3056, NULL),
(3057, 'tone', '/toʊn/', 'noun', '{"zh-TW":["語氣；風格"],"en":["the general character or attitude conveyed in written or spoken communication"]}', NULL, 'professional tone / formal tone / conversational tone', '[{"en":"The memo used a formal tone appropriate for the board.","zh-TW":"備忘錄使用了適合董事會的正式語氣。"},{"en":"Adjust the tone of your email to match the relationship with the recipient.","zh-TW":"調整電子郵件的語氣以配合與收件人的關係。"}]', '{"adjective":"tonal"}', NULL, 1, 3057, NULL),
(3058, 'tool', '/tuːl/', 'noun', '{"zh-TW":["工具；手段"],"en":["a device or implement used for a task"]}', NULL, 'management tool / software tool / essential tool', '[{"en":"Data analytics is an essential business tool.","zh-TW":"數據分析是重要的商業工具。"},{"en":"The new software tool streamlines our workflow.","zh-TW":"新的軟體工具簡化了我們的工作流程。"}]', '{"noun":"tool, toolkit"}', NULL, 1, 3058, NULL),
(3059, 'topic', '/ˈtɑːpɪk/', 'noun', '{"zh-TW":["主題；話題"],"en":["a matter dealt with in discussion"]}', NULL, 'on topic / hot topic / change the topic', '[{"en":"Sustainability is a hot topic in business today.","zh-TW":"永續性是當今商業的熱門話題。"},{"en":"Let''s stay on topic during the meeting.","zh-TW":"讓我們在會議中保持主題不偏離。"}]', '{"noun":"topic","adjective":"topical"}', NULL, 2, 3059, NULL),
(3060, 'tornado', '/tɔːrˈneɪdoʊ/', 'noun', '{"zh-TW":["龍捲風"],"en":["a violently rotating column of air"]}', '{"root":{"text":"tornado","meaning":"turn (旋轉)"},"logic":"源自西班牙語 tornar（轉），指旋轉的風柱。"}', 'tornado warning / tornado alley', '[{"en":"The tornado destroyed dozens of houses.","zh-TW":"龍捲風摧毀了數十棟房屋。"},{"en":"Tornado warnings were issued for the entire county.","zh-TW":"全縣發布了龍捲風警報。"}]', NULL, NULL, 3, 3060, NULL),
(3061, 'total', '/ˈtoʊtl/', 'noun, adjective, verb', '{"zh-TW":["總計；全部的","合計"],"en":["the complete amount","to amount to"]}', NULL, 'in total / total cost / total revenue', '[{"en":"The total cost of the project is $2 million.","zh-TW":"專案總成本為兩百萬美元。"},{"en":"Sales totaled $5 million this quarter.","zh-TW":"本季銷售額合計五百萬美元。"}]', '{"noun":"total, totality","adjective":"total","adverb":"totally","verb":"total"}', NULL, 2, 3061, NULL),
(3062, 'touch', '/tʌtʃ/', 'noun, verb', '{"zh-TW":["【主要意義-動詞/名詞】觸碰；接觸","【次要意義-名詞】少量；一點點（a touch of）","【次要意義-動詞】感動；使感動","【次要意義-動詞】涉及；關係到（通常用否定）"],"en":["[primary] to make contact with something; the sense of feeling","[secondary - noun] a very small amount of something","[secondary - verb] to affect emotionally; to move someone","[secondary - verb] to concern or relate to (usually in negative forms)"]}', NULL, 'a touch of class / in touch / keep in touch / touch on / touch base', '[{"en":"His speech touched everyone in the room deeply.","zh-TW":"他的演講深深感動了在場的每一個人。"},{"en":"The report touches on several key issues facing the industry.","zh-TW":"報告涉及了行業面臨的幾個關鍵問題。"},{"en":"Please touch base with the client before sending the final proposal.","zh-TW":"在發送最終提案之前，請先與客戶聯絡確認。"}]', '{"adjective":"touching, untouched","noun":"touchstone"}', 'a touch of（一點點）、touch on（涉及）、touch base（聯絡確認）、keep in touch（保持聯絡）均是 TOEIC 職場溝通文章的高頻表達。', 2, 3062, NULL),
(3063, 'touchpoint', '/ˈtʌtʃpɔɪnt/', 'noun', '{"zh-TW":["接觸點"],"en":["any interaction a customer has with a brand during the buying journey"]}', NULL, 'customer touchpoint / map touchpoints / optimize touchpoints', '[{"en":"Each touchpoint is an opportunity to improve customer satisfaction.","zh-TW":"每個接觸點都是提高客戶滿意度的機會。"},{"en":"The customer journey map identifies all key touchpoints.","zh-TW":"客戶旅程圖識別了所有關鍵接觸點。"}]', '{"plural":"touchpoints"}', NULL, 4, 3063, NULL),
(3064, 'tournament', '/ˈtɜːrnəmənt/', 'noun', '{"zh-TW":["錦標賽；比賽"],"en":["a competition with many games"]}', NULL, 'tennis tournament / enter a tournament', '[{"en":"She entered the tennis tournament.","zh-TW":"她參加了網球錦標賽。"},{"en":"The tournament lasts two weeks.","zh-TW":"比賽持續兩週。"}]', NULL, NULL, 4, 3064, NULL),
(3065, 'town', 'taʊn', 'noun', '{"zh-TW":["城鎮；市區","城市"],"en":["a place smaller than a city","an urban area"]}', NULL, 'hometown/small town', '[{"en":"The new factory is located in a small town.","zh-TW":"新工廠位於一個小鎮。"}]', '{"adjective":"town-based"}', NULL, 1, 3065, NULL),
(3066, 'trace', '/treɪs/', 'noun, verb', '{"zh-TW":["痕跡；蹤跡","追蹤；追溯"],"en":["a mark or sign of something","to find or follow"]}', NULL, 'trace back to / without a trace / trace the origin', '[{"en":"We traced the error back to a software bug.","zh-TW":"我們將錯誤追溯到一個軟體漏洞。"},{"en":"There is no trace of the missing shipment.","zh-TW":"失蹤的貨物沒有任何蹤跡。"}]', '{"noun":"trace, traceability","verb":"trace","adjective":"traceable"}', NULL, 2, 3066, NULL),
(3067, 'track', '/træk/', 'noun, verb', '{"zh-TW":["軌道；途徑","追蹤；跟蹤"],"en":["a path or course","to follow the progress of"]}', NULL, 'keep track of / track record / on track', '[{"en":"We need to keep track of all expenses.","zh-TW":"我們需要追蹤所有費用。"},{"en":"The project is on track for completion in June.","zh-TW":"專案按計畫將在六月完成。"}]', '{"noun":"track, tracker, tracking","verb":"track"}', NULL, 2, 3067, NULL),
(3068, 'tracking', '/ˈtrækɪŋ/', 'noun', '{"zh-TW":["追蹤；跟蹤"],"en":["monitoring the location and status of a shipment in transit"]}', NULL, 'package tracking / shipment tracking / real-time tracking', '[{"en":"Customers can monitor deliveries using the online tracking system.","zh-TW":"客戶可以使用線上追蹤系統監控交付情況。"},{"en":"GPS tracking improved visibility across the entire supply chain.","zh-TW":"GPS追蹤提高了整個供應鏈的能見度。"}]', '{"verb":"track","adjective":"tracked"}', NULL, 3, 3068, NULL),
(3069, 'trade', '/treɪd/', 'noun, verb', '{"zh-TW":["貿易；交易","交易；經商"],"en":["the buying and selling of goods","to engage in commerce"]}', NULL, 'international trade / trade agreement / free trade', '[{"en":"International trade expanded rapidly last year.","zh-TW":"去年國際貿易迅速擴張。"},{"en":"The two countries signed a free trade agreement.","zh-TW":"兩國簽署了自由貿易協定。"}]', '{"noun":"trade, trader, trading","verb":"trade"}', NULL, 2, 3069, NULL),
(3070, 'trade-off', '/ˈtreɪd ɒf/', 'noun', '{"zh-TW":["權衡；取捨"],"en":["a situation requiring a balance between two desirable but competing factors"]}', NULL, 'make a trade-off / trade-off between cost and quality', '[{"en":"The manager faced a trade-off between speed and accuracy.","zh-TW":"管理者面臨著速度和準確性之間的取捨。"},{"en":"Any business decision involves trade-offs between competing priorities.","zh-TW":"任何業務決策都涉及競爭優先事項之間的取捨。"}]', '{"verb":"trade off"}', NULL, 3, 3070, NULL),
(3071, 'trademark', '/ˈtreɪdmɑːrk/', 'noun', '{"zh-TW":["商標"],"en":["a symbol or name legally registered for a product"]}', NULL, 'registered trademark / trademark infringement', '[{"en":"Our logo is a registered trademark.","zh-TW":"我們的商標已經註冊。"},{"en":"Trademark infringement can lead to lawsuits.","zh-TW":"商標侵權可能導致訴訟。"}]', '{"noun":"trademark","verb":"trademark","adjective":"trademarked"}', NULL, 3, 3071, NULL),
(3072, 'tradition', '/trəˈdɪʃn/', 'noun', '{"zh-TW":["傳統","傳統；慣例"],"en":["a custom or belief passed through generations","a long-established custom or belief"]}', '{"prefix":{"text":"tra-","meaning":"across (跨越)"},"root":{"text":"dit","meaning":"give (給予)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"跨越世代傳遞下來的東西，即「傳統」。"}', 'cultural tradition / family tradition; long tradition / by tradition / break with tradition', '[{"en":"It is a tradition to eat turkey on Thanksgiving.","zh-TW":"感恩節吃火雞是一項傳統。"},{"en":"We should respect local traditions.","zh-TW":"我們應該尊重當地傳統。"},{"en":"The company has a long tradition of innovation.","zh-TW":"公司有悠久的創新傳統。"},{"en":"They broke with tradition and appointed a young CEO.","zh-TW":"他們打破傳統任命了一位年輕的執行長。"}]', '{"adjective":"traditional","adverb":"traditionally","noun":"tradition"}', NULL, 3, 3072, NULL),
(3073, 'traditional', 'trəˈdɪʃənəl', 'adjective', '{"zh-TW":["傳統的；慣例的","常規的"],"en":["following old customs","long-established"]}', NULL, 'traditional method/traditional market', '[{"en":"The company uses both traditional and digital marketing.","zh-TW":"公司同時使用傳統和數字行銷。"}]', '{"noun":"tradition","adverb":"traditionally"}', NULL, 4, 3073, NULL),
(3074, 'traffic', '/ˈtræfɪk/', 'noun', '{"zh-TW":["交通；流量"],"en":["vehicles moving on roads; the amount of data"]}', NULL, 'web traffic / traffic congestion / traffic flow', '[{"en":"Website traffic increased by 40% after the campaign.","zh-TW":"活動後網站流量增加了40%。"},{"en":"Heavy traffic caused delays for commuters.","zh-TW":"交通擁堵導致通勤者延誤。"}]', '{"noun":"traffic"}', NULL, 3, 3074, NULL),
(3075, 'training', '/ˈtreɪnɪŋ/', 'noun', '{"zh-TW":["培訓；訓練"],"en":["teaching and practice of a skill"]}', NULL, 'employee training / training program', '[{"en":"New employees must complete a two-week training program.","zh-TW":"新員工必須完成兩週的培訓計劃。"},{"en":"Ongoing training keeps skills sharp and relevant.","zh-TW":"持續培訓保持技能的敏銳性和相關性。"}]', '{"verb":"train","noun":"trainer","adjective":"trained"}', NULL, 3, 3075, 469),
(3076, 'trait', '/treɪt/', 'noun', '{"zh-TW":["特徵；特點"],"en":["a distinguishing quality or characteristic"]}', NULL, 'personality trait / key trait / leadership trait', '[{"en":"Adaptability is a key trait for managers.","zh-TW":"適應力是管理者的關鍵特質。"},{"en":"The company values creativity as a core trait.","zh-TW":"公司將創造力視為核心特質。"}]', '{"noun":"trait"}', NULL, 2, 3076, NULL),
(3077, 'transaction', '/trænˈzækʃn/', 'noun', '{"zh-TW":["交易；事務"],"en":["an instance of buying or selling"]}', NULL, 'financial transaction / online transaction / transaction fee', '[{"en":"All transactions are recorded in the system.","zh-TW":"所有交易都記錄在系統中。"},{"en":"There is a small fee per transaction.","zh-TW":"每筆交易有少量手續費。"}]', '{"noun":"transaction","adjective":"transactional"}', NULL, 4, 3077, 234),
